// Draws the state line, county lines, and city lines on a Leaflet map.
// Labels: counties from zoom 7.5, cities from zoom 10.5 (or opts.cityLabelZoom).
// opts.alwaysLabel: city names to label at every zoom. opts.highlightCounty: county drawn in gold.
function addUtahOutlines(map, opts){
  opts = opts || {};
  const hi = opts.highlightCounty;
  L.geoJSON(UTAH_GEO.cities, { interactive: false, style: { color: '#6E4A78', weight: 1, opacity: 0.55, dashArray: '3 3', fillColor: '#6E4A78', fillOpacity: 0.04 } }).addTo(map);
  L.geoJSON(UTAH_GEO.counties, { interactive: false, style: f => (hi && f.properties.n === hi)
    ? { color: '#A9822F', weight: 3, opacity: 0.95, fillColor: '#EDE7D8', fillOpacity: 0.08 }
    : { color: '#14213D', weight: 1.2, opacity: 0.6, fill: false } }).addTo(map);
  L.geoJSON(UTAH_GEO.state, { interactive: false, style: { color: '#A9822F', weight: 3.5, opacity: 0.95, fill: false } }).addTo(map);
  if (!map.getPane('utahLabels')) { map.createPane('utahLabels'); map.getPane('utahLabels').style.zIndex = 450; map.getPane('utahLabels').style.pointerEvents = 'none'; }
  const lab = (f, cls, suffix) => L.marker(f.properties.c, { interactive: false, keyboard: false, pane: 'utahLabels',
    icon: L.divIcon({ className: cls, html: '<span>' + f.properties.n + (suffix || '') + '</span>', iconSize: null }) });
  const always = opts.alwaysLabel || [];
  const countyLabels = L.layerGroup(UTAH_GEO.counties.features.map(f => lab(f, 'county-label', ' Co.')));
  const keyLabels = L.layerGroup(UTAH_GEO.cities.features.filter(f => always.includes(f.properties.n)).map(f => lab(f, 'city-label key')));
  const cityLabels = L.layerGroup(UTAH_GEO.cities.features.filter(f => !always.includes(f.properties.n)).map(f => lab(f, 'city-label')));
  keyLabels.addTo(map);
  function toggle(){
    const z = map.getZoom();
    z >= 7.5 ? countyLabels.addTo(map) : countyLabels.remove();
    z >= (opts.cityLabelZoom || 10.5) ? cityLabels.addTo(map) : cityLabels.remove();
  }
  map.on('zoomend', toggle); toggle();
}
